gQV(){return"\u0627\u0644\u0645\u062c\u0645\u0639 \u0627\u0644\u0635\u062d\u064a \u0627\u0644\u0646\u062e\u0628\u0648\u064a"},
gb2x(){return"\u0645\u062f\u0631\u0628\u0648 \u0627\u0644\u0644\u064a\u0627\u0642\u0629"},
gb2y(){return"\u062a\u0639\u0630\u0631 \u062a\u062d\u0645\u064a\u0644 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0637\u0627\u0642\u0645."},
