gaRL(){return"\u0627\u0644\u0633\u0624\u0627\u0644 \u0627\u0644\u062a\u0627\u0644\u064a"},
gaRD(){return"\u0627\u0643\u062a\u0645\u0644 \u0627\u0644\u0645\u0624\u062a\u0645\u0631"},
gaRB(){return"\u0633\u062a\u0638\u0647\u0631 \u0625\u062c\u0627\u0628\u0627\u062a\u0643 \u063a\u062f\u064b\u0627 \u0641\u064a "},
gaRC(){return" \u2014 \u062a\u0627\u0628\u0639 \u0631\u062f\u0648\u062f \u0641\u0639\u0644 \u0627\u0644\u062c\u0645\u0627\u0647\u064a\u0631 \u0647\u0646\u0627\u0643."},
gaRH(){return"\u0625\u0644\u0649 \u0622\u062e\u0631 \u0627\u0644\u0623\u062e\u0628\u0627\u0631"},
gaVx(){return"\u0644\u0627 \u0631\u062c\u0639\u0629 \u0641\u064a\u0647"},
gaVy(){return"\u062a\u0623\u0643\u064a\u062f \u0627\u0644\u0625\u0639\u0644\u0627\u0646"},
gaVz(){return"\u0625\u0630\u0627 \u0648\u0631\u062f \u0639\u0631\u0636 \u0648\u0627\u062d\u062f \u0628\u0647\u0630\u0627 \u0627\u0644\u0633\u0639\u0631 \u064a\u064f\u0628\u0627\u0639 \u0627\u0644\u0644\u0627\u0639\u0628. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0633\u062d\u0628 \u0627\u0644\u0625\u0639\u0644\u0627\u0646."},
gaVw(){return"\u0641\u062a\u062d \u0627\u0644\u0625\u0639\u0644\u0627\u0646"},
gUd(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0648\u0643\u0627\u0644\u0629 \u062a\u0642\u062f\u0645 \u0639\u0631\u0636\u064b\u0627 \u062d\u0627\u0644\u064a\u064b\u0627 \u2014 \u062d\u0627\u0648\u0644 \u0644\u0627\u062d\u0642\u064b\u0627."},
gaVM(){return"\u062a\u0642\u062f\u0645 \u0627\u0644\u0648\u0643\u0627\u0644\u0627\u062a \u0639\u0631\u0648\u0636 \u0627\u0644\u062a\u0645\u062b\u064a\u0644. \u0627\u0644\u0648\u0643\u0627\u0644\u0629 \u0627\u0644\u0643\u0628\u064a\u0631\u0629 \u062a\u0635\u0644 \u0625\u0644\u0649 \u062f\u0627\u0626\u0631\u0629 \u0623\u0648\u0633\u0639 \u0645\u0646 \u0627\u0644\u0623\u0646\u062f\u064a\u0629\u061b \u0648\u0645\u0627 \u064a\u0635\u0644\u0643 \u0645\u0646 \u062d\u0635\u0629 \u064a\u062e\u062a\u0644\u0641 \u0628\u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0644\u0648\u0643\u0627\u0644\u0629."},
gaVN(){return"\u0627\u0644\u0648\u0643\u0627\u0644\u0629 \u062a\u0642\u062a\u0631\u062d \u0633\u0639\u0631 \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u060c \u0648\u0627\u0644\u0642\u0631\u0627\u0631 \u0644\u0643. \u0625\u0630\u0627 \u0627\u062e\u062a\u0631\u062a \u0633\u0639\u0631\u064b\u0627 \u0623\u0642\u0644 \u0628\u0643\u062b\u064a\u0631 \u0645\u0646 \u0642\u064a\u0645\u0629 \u0627\u0644\u0644\u0627\u0639\u0628 \u0641\u0633\u064a\u0638\u0647\u0631 \u0644\u0643 \u062a\u062d\u0630\u064a\u0631."},
gaVO(){return"\u0628\u0639\u062f \u0627\u0644\u062a\u0623\u0643\u064a\u062f \u0644\u0627 \u064a\u0645\u0643\u0646 \u0633\u062d\u0628 \u0627\u0644\u0625\u0639\u0644\u0627\u0646. \u062d\u062a\u0649 \u0644\u0648 \u0648\u0631\u062f \u0639\u0631\u0636 \u0648\u0627\u062d\u062f \u0628\u0647\u0630\u0627 \u0627\u0644\u0633\u0639\u0631 \u064a\u064f\u0628\u0627\u0639 \u0627\u0644\u0644\u0627\u0639\u0628."},
gaVA(){return"\u0627\u0639\u0631\u0636\u0647 \u0644\u0644\u0628\u064a\u0639"},
gaVS(){return"\u0633\u0639\u0631 \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d \u0627\u0644\u0630\u064a \u0627\u062e\u062a\u0631\u062a\u0647 \u0623\u0642\u0644 \u0628\u0648\u0636\u0648\u062d \u0645\u0646 \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0633\u0648\u0642\u064a\u0629. \u0625\u0630\u0627 \u0648\u0631\u062f \u0639\u0631\u0636 \u0648\u0627\u062d\u062f \u064a\u0631\u062d\u0644 \u0627\u0644\u0644\u0627\u0639\u0628 \u0628\u0647\u0630\u0627 \u0627\u0644\u0645\u0628\u0644\u063a."},
gH8(){return"\u0644\u0627\u0639\u0628 \u062a\u0639\u0627\u0642\u062f\u062a \u0645\u0639\u0647 \u062d\u062f\u064a\u062b\u064b\u0627: \u0633\u0639\u0631 \u0627\u0641\u062a\u062a\u0627\u062d\u0647 \u0642\u0631\u064a\u0628 \u062d\u0627\u0644\u064a\u064b\u0627 \u0645\u0646 \u0645\u0628\u0644\u063a \u0634\u0631\u0627\u0626\u0647\u060c \u0648\u0645\u0639 \u0627\u0644\u0648\u0642\u062a \u064a\u0639\u0643\u0633 \u0642\u064a\u0645\u062a\u0647 \u0627\u0644\u0633\u0648\u0642\u064a\u0629."},
gUg(){return"\u0645\u0646 \u064a\u062a\u0648\u0644\u0649 \u0627\u0644\u0628\u064a\u0639\u061f"},
gaVU(){return"\u0625\u0646 \u0628\u064a\u0639 \u064a\u0635\u0644\u0643"},
gaVT(){return"\u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0633\u0648\u0642\u064a\u0629"},
gaVL(){return"\u062f\u0627\u0626\u0631\u0629 \u0623\u0648\u0633\u0639 \u0645\u0646 \u0627\u0644\u0623\u0646\u062f\u064a\u0629"},
gaVK(){return"\u0645\u0627 \u064a\u0635\u0644\u0643 \u0645\u0646 \u062d\u0635\u0629"},
aW9(a,b,c){return"\u0633\u064a\u064f\u0639\u0631\u0636 "+a+" \u0641\u064a \u0627\u0644\u0645\u0632\u0627\u062f \u0628\u062a\u0645\u062b\u064a\u0644 \u0645\u0646 "+b+"\u060c \u0628\u0633\u0639\u0631 \u0627\u0641\u062a\u062a\u0627\u062d "+c+"."},
aWa(a,b,c,d){return"\u0633\u064a\u064f\u0639\u0631\u0636 "+a+" \u0641\u064a \u0627\u0644\u0645\u0632\u0627\u062f \u0628\u062a\u0645\u062b\u064a\u0644 \u0645\u0646 "+b+"\u060c \u0628\u0633\u0639\u0631 \u0627\u0641\u062a\u062a\u0627\u062d "+c+"\u061b "+d+"."},
